  '[]'::jsonb,
  $t$Figure vivante et en exercice : Paul Biya est président de la République du Cameroun au moment où ce récit est publié. Ce récit est traité en mode « Mémoire » : factuel et neutre, sans glorification ni dénigrement. Les points contestés (élections, bilans humains, révision constitutionnelle de 2026) sont présentés avec les positions en présence et leurs sources ; les rumeurs ne sont mentionnées que comme rumeurs, sans en reprendre le contenu. Les faits sont arrêtés au 8 octobre 2026 et seront mis à jour.$t$,
  10,
  $t$depublie$t$,
  false,
  $t$Paul Biya$t$,
  $t$Second President of the Republic of Cameroon, in office since 6 November 1982, after seven years as Prime Minister under Ahmadou Ahidjo$t$,
  $t$Contemporary (born 1933, president since 1982)$t$,
  $t$Central Africa (Cameroon, born in Bulu country, South region, Dja-et-Lobo department)$t$,
  $t$President of the Republic of Cameroon since 6 November 1982, after seven years as Prime Minister under Ahmadou Ahidjo. Born in 1933 in Mvomeka'a, he survived a coup attempt, weathered an economic crisis, accepted the multiparty system, won Bakassi before international justice, waged war on Boko Haram, faced the Anglophone crisis, removed the limit on terms and won elections of which several remain contested. Story told in "Memory" mode: factual, without glorification or denigration.$t$,
  $t$A living figure, still in office: Paul Biya is President of the Republic of Cameroon at the time this story is published. This story is told in "Memory" mode: factual and neutral, without glorification or denigration. Contested points (elections, death tolls, the 2026 constitutional amendment) are presented with the positions involved and their sources; rumours are mentioned only as rumours, without repeating their content. Events are recorded up to 8 October 2026 and will be updated.$t$,
  $t$[{"date": "13 February 1933", "evenement": "born in Mvomeka'a (southern Cameroon, then under French mandate), son of Étienne Mvondo Assam and Anastasie Eyenga Elle"}, {"date": "1948-1963", "evenement": "seminaries of Édéa and Akono, Lycée Leclerc in Yaoundé (baccalaureate 1956), then in Paris Louis-le-Grand, faculty of law, Sciences Po (1961), IHEOM (1962), DES in public law (1963)"}, {"date": "1962-1975", "evenement": "career in the senior civil service under Ahidjo (chargé de mission at the presidency in 1962, secretary general of the presidency in 1968, Minister of State in 1970), then Prime Minister on 30 June 1975"}, {"date": "4 and 6 November 1982", "evenement": "resignation of Ahmadou Ahidjo, then Paul Biya sworn in as constitutional successor"}, {"date": "6 April 1984", "evenement": "coup attempt by elements of the Republican Guard, after the break with Ahidjo (sentenced to death in absentia in February 1984, sentence commuted); toll of 71 dead according to the government, up to around 1,000 according to other estimates"}, {"date": "1987-1994", "evenement": "economic crisis, agreement with the IMF and the World Bank (1988), cuts to civil servants' salaries (1993), devaluation of the CFA franc (January 1994)"}, {"date": "19 December 1990 and 11 October 1992", "evenement": "return of the multiparty system, then first multiparty presidential election (Biya 39.98%, John Fru Ndi around 36%, result contested by the opposition)"}, {"date": "10 October 2002, 12 June 2006, 14 August 2008", "evenement": "ICJ ruling recognising Cameroon's sovereignty over Bakassi, Greentree Agreement with Nigeria, completion of the transfer of authority"}, {"date": "February-April 2008", "evenement": "riots (40 dead according to the government, 136 to 139 according to NGOs), then constitutional amendment removing term limits"}, {"date": "2014", "evenement": "entry into war against Boko Haram in the Far North (Paris declaration, 17 May 2014)"}, {"date": "Since October 2016", "evenement": "Anglophone crisis, which became an armed conflict in 2017 (more than 7,000 dead and around one million displaced according to the International Crisis Group in 2026); Major National Dialogue from 30 September to 4 October 2019"}, {"date": "12 and 27 October 2025", "evenement": "presidential election, Biya declared elected with 53.66% against 35.19% for Issa Tchiroma Bakary, who contests the result; protests repressed (48 dead according to UN sources cited by Reuters, lower official figures); inauguration on 6 November 2025"}, {"date": "4 and 14 April 2026", "evenement": "adoption and then promulgation of the constitutional amendment creating the post of appointed vice-president (not filled as of 8 October 2026)"}]$t$::jsonb,
  $t$[{"texte": "We are here to declare war on Boko Haram.", "source": "Statement by Paul Biya at the joint press conference of the Paris summit on security in Nigeria, on 17 May 2014, reported by the press and reproduced in documents of the Cameroonian presidency (prc.cm). Original in French: « Nous sommes ici pour déclarer la guerre à Boko Haram. »", "statut_attestation": "attestee"}, {"texte": "[…] the image of the one who brought democracy and prosperity […]", "source": "Words attributed to Paul Biya in an interview from July 1990, cited by the Osidimbea entry and regularly repeated in the Cameroonian press (our translation from the French: « l'image de celui qui a apporté la démocratie et la prospérité »). The exact wording and the outlet that originally published the interview could not be verified against a primary source: reported words, not a certain verbatim quote.", "statut_attestation": "rapportee_par_tiers"}]$t$::jsonb,
  '[]'::jsonb
)
on conflict (slug) do update set
  nom_affiche = excluded.nom_affiche,
  nom_complet = excluded.nom_complet,
  sous_titre = excluded.sous_titre,
  epoque = excluded.epoque,
  region = excluded.region,
  theme = excluded.theme,
  resume_catalogue = excluded.resume_catalogue,
  annee_naissance_indicative = excluded.annee_naissance_indicative,
  annee_mort_indicative = excluded.annee_mort_indicative,
  recit_fr_texte = excluded.recit_fr_texte,
  recit_fr_fichier_source = excluded.recit_fr_fichier_source,
  recit_chapitres_fr = excluded.recit_chapitres_fr,
  recit_en_texte = excluded.recit_en_texte,
  recit_en_fichier_source = excluded.recit_en_fichier_source,
  recit_chapitres_en = excluded.recit_chapitres_en,
  frise_chronologique = excluded.frise_chronologique,
  citations = excluded.citations,
  sources = excluded.sources,
  legendes_associees = excluded.legendes_associees,
  heros_lies = excluded.heros_lies,
  chapitres_storyboard = excluded.chapitres_storyboard,
  statut_recit_texte = excluded.statut_recit_texte,
  statut_narration_audio = excluded.statut_narration_audio,
  statut_video = excluded.statut_video,
  image_carte_catalogue = excluded.image_carte_catalogue,
  narration_audio_fr_url = excluded.narration_audio_fr_url,
  narration_audio_en_url = excluded.narration_audio_en_url,
  video_url = excluded.video_url,
  video_chapitres = excluded.video_chapitres,
  avertissement_lecture = excluded.avertissement_lecture,
  nom_affiche_en = excluded.nom_affiche_en,
  sous_titre_en = excluded.sous_titre_en,
  epoque_en = excluded.epoque_en,
  region_en = excluded.region_en,
  resume_catalogue_en = excluded.resume_catalogue_en,
  avertissement_lecture_en = excluded.avertissement_lecture_en,
  frise_chronologique_en = excluded.frise_chronologique_en,
  citations_en = excluded.citations_en,
  legendes_associees_en = excluded.legendes_associees_en,
  updated_at = now();

commit;

-- Contrôle : doit renvoyer 1 ligne avec chapitres_fr = 4, chapitres_en = 4,
-- frise = 13, frise_en = 13, citations = 2, sources = 17, planches = 96,
-- integrite_ok = true.
select slug, statut_publication, ordre_affichage,
  jsonb_array_length(recit_chapitres_fr) as chapitres_fr,
  jsonb_array_length(recit_chapitres_en) as chapitres_en,
  jsonb_array_length(frise_chronologique) as frise,
  jsonb_array_length(frise_chronologique_en) as frise_en,
  jsonb_array_length(citations) as citations,
  cardinality(sources) as sources,
  (select sum((c->>'nb_planches')::int) from jsonb_array_elements(chapitres_storyboard) c) as planches,
  contenu_hash is not null as integrite_ok,
  image_carte_catalogue
from public.heros
where slug = 'paul-biya';
